//! The same workload as Fluent `.ftl` files (plans/16 A2): one file per
//! source file per locale, from the same bodies the `.mf2` files render, so
//! messages, argument names and plural selections are the same.
//!
//! Layout of a file (what `fluent-syntax`'s serializer would write, plus a
//! blank line before each commented entry):
//!
//! ```text
//! ### chat.ftl — generated by workload-gen (…); do not edit by hand.
//! ### resource comment
//!
//! ## chat.input
//! ## section comment
//!
//! # entry comment
//! # Variables:
//! #   $count (Number) - …
//! chat-input-unread = You have { $count } unread messages
//! chat-input-send = Send
//! chat-input-select =
//!     { $count ->
//!         [one] …
//!        *[other] …
//!     }
//! chat-input-hint =
//!     .before = Press
//!     .kbd = Esc
//!     .after = to close.
//! ```
//!
//! What Fluent cannot say the same way:
//!
//! * **Ids.** A Fluent identifier has no `.`, so the dotted id is written with
//!   `-` for `.` (`chat.input.send` → `chat-input-send`); a section becomes a
//!   group comment naming it (`## chat.input`), which does not touch ids.
//!   Generation fails if two ids would meet.
//! * **Markup** (plans/16 A5's like-with-like rule; 04 §11 item 1). Fluent
//!   has none, so a sentence with an element is split around it, the way an
//!   application without markup must: attributes `.before`, `.<element>`
//!   (the element's text) and `.after`, always all three, the view putting
//!   the element and the spaces between them. An empty part is `{ "" }`.
//! * **`@param`** has no Fluent counterpart; each becomes a line of the
//!   entry's comment in the usual `# Variables:` block.
//! * **Functions** (`--number`, `--datetime`): `:number` → `NUMBER` with the
//!   same options; `:datetime` → the nearest `DATETIME` (Fluent's options
//!   are `Intl.DateTimeFormat`'s, so there is no identity; see plans/05
//!   §6.1).

use std::collections::BTreeMap;

use crate::error::Error;
use crate::model::{Body, Func, Part, Pattern, Var, VarKind, Workload};
use crate::resource::{self, Comments, param_description};

/// Attribute holding the text before the element of a split sentence.
pub const BEFORE: &str = "before";
/// Attribute holding the text after the element of a split sentence.
pub const AFTER: &str = "after";

/// The Fluent id of a dotted MF2 id: `.` → `-`.
pub fn id(mf2_id: &str) -> String {
    mf2_id.replace('.', "-")
}

/// Whether `name` is a Fluent identifier: `[a-zA-Z][a-zA-Z0-9_-]*`.
pub fn is_identifier(name: &str) -> bool {
    let mut bytes = name.bytes();
    bytes.next().is_some_and(|b| b.is_ascii_alphabetic())
        && bytes.all(|b| b.is_ascii_alphanumeric() || matches!(b, b'_' | b'-'))
}

/// The Fluent id of every message, indexed like `wl.messages`; fails if one
/// is not an identifier or two meet.
pub fn ids(wl: &Workload) -> Result<Vec<String>, Error> {
    let mut seen: BTreeMap<String, &str> = BTreeMap::new();
    let mut out = Vec::with_capacity(wl.messages.len());
    for m in &wl.messages {
        let fid = id(&m.id);
        if !is_identifier(&fid) {
            return Err(Error::Knobs(format!(
                "`{}` is not a Fluent identifier as `{fid}`",
                m.id
            )));
        }
        if let Some(other) = seen.insert(fid.clone(), &m.id) {
            return Err(Error::Knobs(format!(
                "`{other}` and `{}` are both `{fid}` in Fluent",
                m.id
            )));
        }
        out.push(fid);
    }
    Ok(out)
}

/// The variable's type as the `# Variables:` convention names it.
fn kind_name(kind: VarKind) -> &'static str {
    match kind {
        VarKind::Num => "Number",
        VarKind::Str => "String",
        VarKind::Date => "Date",
    }
}

/// A placeable for a variable, with the function its MF2 placeholder has.
fn placeable(var: &Var, out: &mut String) {
    let name = var.name;
    out.push_str("{ ");
    match var.func {
        Func::Plain | Func::Integer => {
            out.push('$');
            out.push_str(name);
        }
        Func::Number(k) => {
            out.push_str("NUMBER($");
            out.push_str(name);
            out.push_str(match k {
                0 => "",
                1 => ", minimumFractionDigits: 2",
                _ => ", maximumFractionDigits: 0",
            });
            out.push(')');
        }
        Func::DateTime(k) => {
            out.push_str("DATETIME($");
            out.push_str(name);
            out.push_str(match k {
                0 => ", dateStyle: \"medium\", timeStyle: \"short\"",
                1 => ", dateStyle: \"short\", timeStyle: \"short\"",
                _ => ", month: \"short\", day: \"numeric\", hour: \"numeric\"",
            });
            out.push(')');
        }
    }
    out.push_str(" }");
}

/// An inline pattern (no markup); `{ "" }` when it is empty.
fn inline(pattern: &[Part], vars: &[Var], out: &mut String) {
    let start = out.len();
    for part in pattern {
        match part {
            Part::Text(t) => {
                debug_assert!(!t.contains(['{', '}', '\n']), "{t:?}");
                out.push_str(t);
            }
            Part::Var(i) => placeable(&vars[*i], out),
            Part::Markup { .. } => unreachable!("markup is split into attributes"),
        }
    }
    if out.len() == start {
        out.push_str("{ \"\" }");
    }
}

/// A sentence with an element, split around it: `(before, element, after)`
/// as attribute name and pattern, the text trimmed at the split (the view
/// supplies the spaces).
fn split(pattern: &[Part]) -> Vec<(&str, Pattern)> {
    let at = pattern
        .iter()
        .position(|p| matches!(p, Part::Markup { .. }))
        .unwrap_or(pattern.len());
    let trim = |parts: &[Part], start: bool| -> Pattern {
        let mut parts = parts.to_vec();
        let edge = if start {
            parts.last_mut()
        } else {
            parts.first_mut()
        };
        if let Some(Part::Text(t)) = edge {
            *t = if start { t.trim_end() } else { t.trim_start() }.to_owned();
        }
        parts.retain(|p| !matches!(p, Part::Text(t) if t.is_empty()));
        parts
    };
    let mut out = vec![(BEFORE, trim(&pattern[..at], true))];
    if let Some(Part::Markup { name, inner }) = pattern.get(at) {
        out.push((*name, vec![Part::Text(inner.clone())]));
        debug_assert!(
            !pattern[at + 1..]
                .iter()
                .any(|p| matches!(p, Part::Markup { .. })),
            "one element per message"
        );
        out.push((AFTER, trim(&pattern[at + 1..], false)));
    }
    out
}

/// The entry: `id = …` and its value's lines, each ending in LF.
pub fn write_entry(out: &mut String, fid: &str, body: &Body, vars: &[Var]) {
    out.push_str(fid);
    out.push_str(" =");
    match body {
        Body::Pattern(p) if p.iter().any(|x| matches!(x, Part::Markup { .. })) => {
            out.push('\n');
            for (name, part) in split(p) {
                out.push_str("    .");
                out.push_str(name);
                out.push_str(" = ");
                inline(&part, vars, out);
                out.push('\n');
            }
        }
        Body::Pattern(p) => {
            out.push(' ');
            inline(p, vars, out);
            out.push('\n');
        }
        Body::Select { selector, variants } => {
            out.push_str("\n    { $");
            out.push_str(vars[*selector].name);
            out.push_str(" ->\n");
            for (key, pattern) in variants {
                if key == "*" {
                    out.push_str("       *[other] ");
                } else {
                    out.push_str("        [");
                    out.push_str(key);
                    out.push_str("] ");
                }
                inline(pattern, vars, out);
                out.push('\n');
            }
            out.push_str("    }\n");
        }
    }
}

fn write_comment(out: &mut String, sigil: &str, lines: &[String]) {
    for line in lines {
        out.push_str(sigil);
        if !line.is_empty() {
            out.push(' ');
            out.push_str(line);
        }
        out.push('\n');
    }
}

/// Makes sure the output ends with a blank line (unless it is empty).
fn blank_line(out: &mut String) {
    if !out.is_empty() && !out.ends_with("\n\n") {
        out.push('\n');
    }
}

/// Plans the comments of file `fi` as Fluent, so that they are 60 % of the
/// source locale's bytes as the `.mf2` files' are: the same slots, sized for
/// Fluent's own comment lines (`# Variables:`, `## <section>`).
pub fn plan_comments(wl: &Workload, fi: usize, ids: &[String], en_bodies: &[Body]) -> Comments {
    resource::plan(wl, fi, "ftl", &|c| write_file(wl, fi, ids, en_bodies, c))
}

/// Writes file `fi` of one locale as Fluent, from per-message `bodies` and
/// Fluent `ids`.
pub fn write_file(
    wl: &Workload,
    fi: usize,
    ids: &[String],
    bodies: &[Body],
    comments: &Comments,
) -> String {
    let file = &wl.files[fi];
    let mut out = String::new();
    write_comment(&mut out, "###", &comments.header);
    for (si, section) in file.sections.iter().enumerate() {
        if let Some(head) = &section.head {
            blank_line(&mut out);
            let mut lines = vec![head.clone()];
            lines.extend(comments.sections[si].iter().flatten().cloned());
            write_comment(&mut out, "##", &lines);
        }
        blank_line(&mut out);
        for &j in &section.messages {
            let message = &wl.messages[j];
            let commented = comments.entries[j].is_some();
            let mut lines = comments.entries[j].clone().unwrap_or_default();
            if !message.vars.is_empty() {
                lines.push("Variables:".to_owned());
                for (v, var) in message.vars.iter().enumerate() {
                    lines.push(format!(
                        "  ${} ({}) - {}",
                        var.name,
                        kind_name(var.kind),
                        param_description(wl.knobs.seed, j, message, v)
                    ));
                }
            }
            if commented || !lines.is_empty() {
                blank_line(&mut out);
                write_comment(&mut out, "#", &lines);
            }
            write_entry(&mut out, &ids[j], &bodies[j], &message.vars);
        }
    }
    out
}
